put\n(build/main.js).\n\nChanges:\n- Fix common.main in io-package.json to build/main.js\n- Fix package.json main field to build/main.js\n- Add build-time validation script (scripts/validate-entrypoint.js)\n- Add postbuild step to package.json to catch future mismatches\n- Add GitHub Actions CI workflow with build + entry point validation\n\nCo-Authored-By: Claude Opus 4.8 <noreply@anthropic.com>","tree":{"sha":"fb0934c0a654b7d5ff9478fbabab4b86053189af","url":"https://api.github.com/repos/realrubbish/iobroker-fmd/git/trees/fb0934c0a654b7d5ff9478fbabab4b86053189af"},"url":"https://api.github.com/repos/realrubbish/iobroker-fmd/git/commits/aa4170c050fd5a54add51fb72a1d4ef4a2aac03c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/225377338?v=4","events_url":"https://api.github.com/users/toBYTEas/events{/privacy}","followers_url":"https://api.github.com/users/toBYTEas/followers","following_url":"https://api.github.com/users/toBYTEas/following{/other_user}","gists_url":"https://api.github.com/users/toBYTEas/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/toBYTEas","id":225377338,"login":"toBYTEas","node_id":"U_kgDODW78Og","organizations_url":"https://api.github.com/users/toBYTEas/orgs","received_events_url":"https://api.github.com/users/toBYTEas/received_events","repos_url":"https://api.github.com/users/toBYTEas/repos","site_admin":false,"starred_url":"https://api.github.com/users/toBYTEas/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/toBYTEas/subscriptions","type":"User","url":"https://api.github.com/users/toBYTEas","user_view_type":"public"},"html_url":"https://github.com/realrubbish/iobroker-fmd/commit/aa4170c050fd5a54add51fb72a1d4ef4a2aac03c","node_id":"C_kwDOSw1L3toAKGFhNDE3MGMwNTBmZDVhNTRhZGQ1MWZiNzJhMWQ0ZWY0YTJhYWMwM2M","parents":[{"html_url":"https://github.com/realrubbish/iobroker-fmd/commit/6ef57